# [LATER-STEP] caption_embedding.py\n# Embed live caption chunks for semantic search within a meeting using IBM\n# watsonx.ai text embeddings service.\n\nimport asyncio\nimport json\nimport os\nimport sys\nfrom ibm_watson import WatsonNaturalLanguageUnderstandingV1\nfrom ibm_cloud_sdk_core.authenticators import IAMAuthenticator\n\n# ----------------------------------------------------------\n# Provider configuration\n# ----------------------------------------------------------\nAPIKEY = os.getenv('WATSONX_APIKEY')\nURL = os.getenv('WATSONX_URL', 'https://api.us-south.natural-language-understanding.watson.cloud.ibm.com')\nif not APIKEY:\n    print('Set WATSONX_APIKEY environment variable')\n    sys.exit(1)\nauthenticator = IAMAuthenticator(APIKEY)\nembedding = WatsonNaturalLanguageUnderstandingV1(\n    version='2023-08-01',\n    authenticator=authenticator,\n)\nembedding.set_service_url(URL)\n\n# ----------------------------------------------------------\n# Helper: generate embedding for a text chunk\n# ----------------------------------------------------------\nasync def embed(text: str) -> list:\n    \"\"\"Return a list of floats representing the embedding vector.\n\n    The Watson NLU `embed` endpoint returns `vector` as a list of floats.\n    \"\"\"\n    try:\n        response = embedding.analyze(\n            text=text,\n            features={\n                'embeddings': {},\n            },\n        ).get_result()\n        vec = response.get('embeddings', [{}])[0].get('vector')\n        return vec if vec else []\n    except Exception as e:\n        print('Embedding error:', e)\n        return []\n\n# ----------------------------------------------------------\n# Integration with caption stream\n# ----------------------------------------------------------\n# This example uses a dummy caption generator; replace with real stream.\n# ----------------------------------------------------------\nasync def caption_generator():\n    # Simulated live captions\n    for txt in ['The project timeline is delayed.', 'Next steps: finalize design specs.']:\n        yield {'transcript': txt, 'final': True}\n\n# ----------------------------------------------------------\n# Main loop\n# ----------------------------------------------------------\nasync def main():\n    async for chunk in caption_generator():\n        txt = chunk['transcript']\n        print('Caption chunk:', txt)\n        vec = await embed(txt)\n        print('Embedding vector (first 5 values):', vec[:5] if vec else [])\n\nif __name__ == '__main__':\n    asyncio.run(main())\n